const MID = 362;

/** Spiegelt einen Pfad (nur absolute M/L/C/Z) an der Mittelachse und verschiebt ihn um dx */
function mirror(d: string, dx = 0): string {
  let n = 0;
  return d.replace(/[MLCZ]|-?\d+(?:\.\d+)?/g, (t) => {
    if (/[MLCZ]/.test(t)) { n = 0; return t; }
    const v = Number(t);
    return String(n++ % 2 === 0 ? 2 * MID - v + dx : v);
  });
}
function shift(d: string, dx: number): string {
  let n = 0;
  return d.replace(/[MLCZ]|-?\d+(?:\.\d+)?/g, (t) => {
    if (/[MLCZ]/.test(t)) { n = 0; return t; }
    const v = Number(t);
    return String(n++ % 2 === 0 ? v + dx : v);
  });
}
/** Linke Hälfte so, wie gezeichnet; rechte Hälfte gespiegelt */
const pair = (...ds: string[]): AnatomyPart => ({ l: ds, r: ds.map((d) => mirror(d)) });
/** Mittige Fläche (liegt auf der Achse) */
const mid = (...ds: string[]): AnatomyPart => ({ c: ds });
/** Linke Hälfte + gespiegelte rechte Hälfte als eine zusammenhängende mittige Fläche (an der Achse verbunden) */
const rows = (n: number, y0: number, y1: number, x0: number, x1: number, gap = 5): string[] => {
  const out: string[] = [];
  const h = (y1 - y0) / n;
  for (let i = 0; i < n; i++) {
    const a = y0 + i * h + gap / 2;
    const b = y0 + (i + 1) * h - gap / 2;
    const bulge = 5;
    out.push(`M ${x0 + 2} ${a} C ${x0 + 14} ${a - bulge} ${x1 - 10} ${a - bulge} ${x1} ${a} L ${x1} ${b} C ${x1 - 10} ${b + bulge} ${x0 + 14} ${b + bulge} ${x0 + 2} ${b} Z`);
  }
  return out;
};

